/// <summary>
/// Service class for CB525 - Vendor Returns - Invoicing.
/// </summary>
class MetVendorReturnInvoiceCreationService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// Process the main logic of the class.
/// Fetch the PO from query and create the pending vendor invoice after validation.
/// </summary>
/// <param name = "_contract">MetVendorReturnInvoiceCreationContract</param>
public void process(MetVendorReturnInvoiceCreationContract _contract)
{
    Query       query       = new Query(SysOperationHelper::base64Decode(_contract.parmPackedQuery()));
    QueryRun    queryRun    = new QueryRun(query);

    while (queryRun.next())
    {
        boolean                 createInvoice   = false;
        PurchTable              purchTable      = queryRun.get(tableNum(PurchTable));

        if (purchTable.PurchStatus == PurchStatus::Received)
        {
            VendPackingSlipJour     vendPackingSlipJour;
            VendInvoiceInfoTable    vendInvoiceInfoTableLoc, vendInvoiceInfoTableExist;
            VendInvoiceInfoLine     vendInvoiceInfoLine;
            VendPackingSlipTrans    vendPackingSlipTrans;
            VendInvoiceInfoSubLine  vendInvoiceInfoSubLine;

            //Iterate through all the product receipt on the PO.
            while select vendPackingSlipJour
                where vendPackingSlipJour.PurchId == purchTable.PurchId
            {
                VendInvoicePackingSlipQuantityMatch vendInvoicePkSlipQtyMatch;

                //Check If Return Invoice already created
                select firstonly RecId from vendInvoiceInfoTableExist
                    where vendInvoiceInfoTableExist.PurchId == vendPackingSlipJour.PurchId
                    && vendInvoiceInfoTableExist.METReturnInvoice == NoYes::Yes;

                //Validate if a pending vendor invoice jour exists for the PO or one of the product receipt in case of multiple records.
                select firstonly RecId from vendInvoiceInfoTableLoc where vendInvoiceInfoTableLoc.PurchId == purchTable.PurchId
                    exists join vendInvoiceInfoLine
                    where vendInvoiceInfoLine.ParmId == vendInvoiceInfoTableLoc.ParmId
                        && vendInvoiceInfoLine.TableRefId == vendInvoiceInfoTableLoc.TableRefId
                    exists join vendInvoiceInfoSubLine
                    where vendInvoiceInfoSubLine.LineRefRecId == vendInvoiceInfoLine.RecId
                    && vendInvoiceInfoSubLine.DocumentId == vendPackingSlipJour.PackingSlipId;

                //Check if the invoice journal already exists for the packing slip.
                select firstonly RecId from vendInvoicePkSlipQtyMatch
                    join vendPackingSlipTrans
                    where vendPackingSlipTrans.VendPackingSlipJour == vendPackingSlipJour.RecId
                    && vendInvoicePkSlipQtyMatch.PackingSlipSourceDocumentLine == vendPackingSlipTrans.SourceDocumentLine;

                if (!vendInvoiceInfoTableLoc.RecId && !vendInvoicePkSlipQtyMatch.RecId && !vendInvoiceInfoTableExist.RecId)
                {
                    createInvoice = true;

                    ttsbegin;
                    VendInvoiceInfoTable vendInvoiceInfoTable = this.createPendingVendorInvoice(purchTable);

                    if (vendInvoiceInfoTable.RecId)
                    {
                        this.createPendingVendorInvoiceLines(purchTable, vendInvoiceInfoTable);
                    }
                    ttscommit;

                    // Bug 291344: CB525- Vendor return invoice batch job is failing due to workflow
                    // To delete the parmId simulating the pending vendor invoice to be closed.
                    VendInvoiceInfoTable::moveFromActiveToSaved(vendInvoiceInfoTable);
                    vendInvoiceInfoTable.reread();

                    this.submitClaimInvoiceToWorkflow(vendInvoiceInfoTable);
                }
            }
        }
    }

}

/// <summary>
/// Create the pending vendor invoice of the PO.
/// </summary>
/// <param name = "_purchTable">PurchTable</param>
/// <param name = "_invoiceQty">VendPackingSlipTrans</param>
/// <returns></returns>
public VendInvoiceInfoTable createPendingVendorInvoice(PurchTable _purchTable)
{
    MetImportGST            importGST;
    MetImportAmount         importAmount;
    Purchtotals             purchTotals = Purchtotals::newPurchTable(_purchTable);
    VendInvoiceInfoTable    vendInvoiceInfoTable;

    purchTotals.calc();

    importGST    = purchTotals.taxTotal();
    importAmount = purchTotals.purchTotalAmount();

    vendInvoiceInfoTable.clear();
    vendInvoiceInfoTable.initValue();
    vendInvoiceInfoTable.initFromPurchTable(_purchTable);
    vendInvoiceInfoTable.DocumentOrigin = DocumentOrigin::Manual;
    vendInvoiceInfoTable.defaultRow(null, null, true);

    vendInvoiceInfoTable.ParmId                 = formletterParmData::getNewParmId();
    vendInvoiceInfoTable.DocumentDate           = vendInvoiceInfoTable.ReceivedDate;
    vendInvoiceInfoTable.TableRefId             = formletterParmData::getNewTableRefId();
    vendInvoiceInfoTable.Approved               = NoYes::Yes;
    vendInvoiceInfoTable.MetImportAmount        = importAmount;
    vendInvoiceInfoTable.MetImportGST           = importGST;
    vendInvoiceInfoTable.METClaimInvoice        = NoYes::Yes;

    // Saving or Posting will update this value, at this point we only want to flag that the value is something other than LastMatchVarianceOptions::Unknown
    vendInvoiceInfoTable.LastMatchVariance      = LastMatchVarianceOptions::OK;

    vendInvoiceInfoTable.Payment                = VendTable::find(_purchTable.InvoiceAccount).PaymTermId;
    vendInvoiceInfoTable.METSkipInvoiceMatching = NoYes::Yes;
    vendInvoiceInfoTable.METReturnInvoice       = NoYes::Yes;

    // Bug 291344: CB525- Vendor return invoice batch job is failing due to workflow
    // Simulating what is being done in VendInvoiceHeaderWorkflow\main so amount invoice matching does not fail.
    vendInvoiceInfoTable.PerformFullInvoiceMatching = NoYes::Yes;

    NumberSequenceReference numberSequenceReference;

    numberSequenceReference = NumberSeqReference::findReference(extendedTypeNum(METVendReturnInvoiceNumber));

    if (numberSequenceReference.RecId)
    {
        METVendReturnInvoiceNumber num  = NumberSeq::newGetNum(numberSequenceReference).num();
        vendInvoiceInfoTable.Num        = num;
    }

    vendInvoiceInfoTable.Description = _purchTable.PurchId;

    if(vendInvoiceInfoTable.validateWrite())
    {
        VendInvoiceInfoSubTable::createFromVendInvoiceInfoTable(vendInvoiceInfoTable, true);
        vendInvoiceInfoTable.insert();
    }

    return vendInvoiceInfoTable;
}

/// <summary>
/// Create the pending vendor invoice lines of the PO.
/// </summary>
/// <param name = "_vendInvoiceInfoTable">VendInvoiceInfoTable</param>
/// <param name = "_purchLine">PurchLine</param>
/// <param name = "_invoiceQty">VendPackingSlipTrans</param>
public void createPendingVendorInvoiceLines(PurchTable _purchTable,
    VendInvoiceInfoTable _vendInvoiceInfoTable)
{
    PurchLine               purchLine;
    VendInvoiceInfoLine     vendInvoiceInfoLine;

    while select purchLine
        where purchLine.PurchId == _purchTable.PurchId
    {
        vendInvoiceInfoLine.clear();

        vendInvoiceInfoLine.initValue();
        vendInvoiceInfoLine.defaultRow(purchLine);
        vendInvoiceInfoLine.initFromPurchLine(purchLine);

        vendInvoiceInfoLine.ParmId              = _vendInvoiceInfoTable.ParmId;
        vendInvoiceInfoLine.LineNum             = any2int(purchLine.LineNumber);
        vendInvoiceInfoLine.OrigPurchId         = purchLine.PurchId;
        vendInvoiceInfoLine.DeliveryName        = _vendInvoiceInfoTable.DeliveryName;
        vendInvoiceInfoLine.TableRefId          = _vendInvoiceInfoTable.TableRefId;
        vendInvoiceInfoLine.currencyCode        = _vendInvoiceInfoTable.CurrencyCode;

        vendInvoiceInfoLine.InvoiceAccount      = _vendInvoiceInfoTable.InvoiceAccount;
        vendInvoiceInfoLine.InventDimId         = purchLine.InventDimId;
        vendInvoiceInfoLine.OrderAccount        = _vendInvoiceInfoTable.OrderAccount;
        vendInvoiceInfoLine.ItemId              = purchLine.ItemId;
        vendInvoiceInfoLine.InventTransId       = purchLine.InventTransId;

        vendInvoiceInfoLine.DocumentOrigin      = DocumentOrigin::Manual;
        vendInvoiceInfoLine.ReceiveNow          = purchLine.PurchQty;

        vendInvoiceInfoLine.PurchUnit           = purchLine.PurchUnit;
        vendInvoiceInfoLine.PurchPrice          = purchLine.PurchPrice;

        // Bug 291957: CB705- Vendor return batch job is triggering error and not posting the return invoice
        InventUnitId inventUnitId               = InventTableModule::find(purchLine.ItemId, ModuleInventPurchSales::Invent).UnitId;
        vendInvoiceInfoLine.InventNow           = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(purchLine.ItemId,
                                                                                    purchLine.InventDimId,
                                                                                    purchLine.PurchQty,
                                                                                    purchLine.PurchUnit,
                                                                                    inventUnitId);

        vendInvoiceInfoLine.LineAmount          = purchLine.LineAmount;
        vendInvoiceInfoLine.DefaultDimension    = purchLine.DefaultDimension;
        vendInvoiceInfoLine.ProcurementCategory = EcoResProductCategory::findByItemIdCategoryHierarchyRole(purchLine.ItemId, EcoResCategoryNamedHierarchyRole::Procurement).Category;

        //Force trigger variance calculation on lines.
        if(vendInvoiceInfoLine.isNonPO())
        {
            vendInvoiceInfoLine.metFetchInitializeReasonCode();
        }
        //Insert pending invoice lines.
        vendInvoiceInfoLine.insert();

        //Insert pending invoice sub-lines.
        this.createPendingVendorInvoiceInfoSubLines(purchLine.InventTransId, vendInvoiceInfoLine);
    }
}

/// <summary>
/// Create the pending vendor invoice lines of the PO.
/// </summary>
/// <param name = "_vendInvoiceInfoTable">VendInvoiceInfoTable</param>
/// <param name = "_purchLine">PurchLine</param>
/// <param name = "_invoiceQty">VendPackingSlipTrans</param>
public void createPendingVendorInvoiceInfoSubLines(InventTransId _inventTransId, VendInvoiceInfoLine _vendInvoiceInfoLine)
{
    VendPackingSlipTrans    vendPackingSlipTrans;
    VendInvoiceInfoSubLine  vendInvoiceInfoSubLine;

    vendInvoiceInfoSubLine.clear();

    //Insert the sub line details from the table <c>VendPackingSlipTrans</c>
    while select InventTransId, PackingSlipId, Qty, RecId, TableId from vendPackingSlipTrans
        where vendPackingSlipTrans.InventTransId ==_inventTransId
    {
        vendInvoiceInfoSubLine.initValue();
        vendInvoiceInfoSubLine.defaultRow();

        vendInvoiceInfoSubLine.ParmId               = _vendInvoiceInfoLine.ParmId;
        vendInvoiceInfoSubLine.InventNow            = vendPackingSlipTrans.Qty;
        vendInvoiceInfoSubLine.ReceiveNow           = vendPackingSlipTrans.Qty;
        vendInvoiceInfoSubLine.DocumentId           = vendPackingSlipTrans.PackingSlipId;
        vendInvoiceInfoSubLine.LineRefRecId         = _vendInvoiceInfoLine.RecId;
        vendInvoiceInfoSubLine.JournalRefRecId      = vendPackingSlipTrans.RecId;
        vendInvoiceInfoSubLine.JournalRefTableId    = vendPackingSlipTrans.TableId;

        vendInvoiceInfoSubLine.insert();
    }
}

/// <summary>
/// Submit claim to workflow.
/// </summary>
/// <param name = "_claimInvoiceTable">VendInvoiceInfoTable</param>
private void submitClaimInvoiceToWorkflow(VendInvoiceInfoTable _claimInvoiceTable)
{
    if(_claimInvoiceTable && _claimInvoiceTable.existLine() && _claimInvoiceTable.canSubmitToWorkflow())
    {
        VendInvoiceHeaderWorkflow::submitToWorkflow(_claimInvoiceTable, _claimInvoiceTable.Description);
    }
}
